{
#define bitint uint64_t
#define MASK1 0x0101010101010101ull
#define MASK2 0x7f7f7f7f7f7f7f7full
#define MASK3 0x8080808080808080ull
#define MASK4 0x80

  const bitint first = MASK1 * (uint8_t)xs[0];
